import{_ as o,o as t,c as d,a3 as a}from"./chunks/framework.WFmvnizL.js";const m=JSON.parse('{"title":"Dashboard 与 MCP 扩展","description":"扩展哪吒 Dashboard 的 REST、MCP 和异步任务时，如何沿现有架构实现权限、输入校验、API 契约、取消、审计与回归测试。","frontmatter":{"description":"扩展哪吒 Dashboard 的 REST、MCP 和异步任务时，如何沿现有架构实现权限、输入校验、API 契约、取消、审计与回归测试。","outline":"deep"},"headers":[],"relativePath":"developer/backend-development.md","filePath":"developer/backend-development.md","lastUpdated":1792850916000}'),r={name:"developer/backend-development.md"};function c(l,e,h,n,i,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="dashboard-与-mcp-扩展" tabindex="-1">Dashboard 与 MCP 扩展 <a class="header-anchor" href="#dashboard-与-mcp-扩展" aria-label="Permalink to &quot;Dashboard 与 MCP 扩展&quot;">​</a></h1><p>优先复用现有 REST API 和能力层。新增一个接口不仅是注册路由，还包括资源权限、输入约束、响应语义和生命周期。</p><h2 id="按职责定位" tabindex="-1">按职责定位 <a class="header-anchor" href="#按职责定位" aria-label="Permalink to &quot;按职责定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>修改范围</th></tr></thead><tbody><tr><td>HTTP 路由和中间件</td><td><code>cmd/dashboard/controller/controller.go</code></td><td>鉴权组、scope、CSRF、路由注册</td></tr><tr><td>请求/响应与持久模型</td><td><code>model</code></td><td>表单、校验、JSON、数据库结构</td></tr><tr><td>处理器</td><td><code>cmd/dashboard/controller</code></td><td>HTTP/MCP 协议与业务调用</td></tr><tr><td>共享业务与存储</td><td><code>service/singleton</code>、<code>pkg/tsdb</code></td><td>缓存、历史、告警、任务生命周期</td></tr><tr><td>Agent 通信</td><td><code>cmd/dashboard/rpc</code>、<code>service/rpc</code>、<code>proto</code></td><td>gRPC、任务派发、流与回执</td></tr></tbody></table><p>避免让 UI 提交 ORM 模型中的所有字段。请求、数据库和公开响应应有各自明确的字段边界。</p><h2 id="新增-rest-能力的顺序" tabindex="-1">新增 REST 能力的顺序 <a class="header-anchor" href="#新增-rest-能力的顺序" aria-label="Permalink to &quot;新增 REST 能力的顺序&quot;">​</a></h2><ol><li>定义调用者、输入、返回和资源访问规则；确定是游客可读、成员资源还是管理员能力。</li><li>在 <code>model</code> 定义表单与响应，使用明确的 JSON 字段，验证大小、范围和枚举。</li><li>复用路由的 JWT/PAT 鉴权，并添加真实的 scope 门禁。浏览器 cookie 写请求继续受 CSRF 保护。</li><li>逐资源检查归属/可见性及 PAT 服务器范围，不能只检查“已登录”。不存在与不可访问资源避免泄漏差异。</li><li>使用现有响应包装，区分空结果、权限错误、暂不可用及任务接受；添加 Swagger 注释并重新生成。</li><li>补成功、越权、缺失 scope、白名单外 ID、无效输入和并发/取消测试，再同步前端及双语文档。</li></ol><p><strong>读权限不等于管理权限。</strong> 多用户公开服务器可以被成员看见，但并不因此允许修改或执行任务。历史查询同样要执行可见性和 PAT 限制。</p><h2 id="增加-mcp-工具" tabindex="-1">增加 MCP 工具 <a class="header-anchor" href="#增加-mcp-工具" aria-label="Permalink to &quot;增加 MCP 工具&quot;">​</a></h2><p>现有原生 MCP 工具集中在身份、服务器清单/状态、命令和文件；告警配置、历史与任务管理不是自动存在的 MCP 方法。先查<a href="/guide/mcp.html">当前工具清单</a>，不要仅在宣传或客户端中起一个名字就当作服务端已实现。</p><p>源码入口为 <code>controller/mcp.go</code>、<code>mcp_tools_*.go</code>、<code>mcp_transfer.go</code> 及 <code>service/rpc</code> 相关实现。扩展时同时完成：</p><ul><li>JSON-RPC 参数 schema、工具注册与调用分发，协议版本/错误处理遵循现有实现。</li><li><code>enable_mcp</code> 总开关、PAT-only 鉴权、Origin 限制，不能退回浏览器 JWT。</li><li>工具最小 scope、用户资源权限、PAT 服务器范围，以及 Agent 对应能力开关。</li><li>输入/输出上限、超时和取消、PAT 吊销、MCP 关闭时的在途操作回收。</li><li>命令退出码与执行失败的不同语义；任务应答不能冒充进程执行成功。</li><li>审计记录工具、目标、结果与必要元数据，但不记录 PAT、文件敏感正文或多余命令输出。</li></ul><p>对文件工具复用路径限制、大小限制与传输完整性检查。不要自己增加绕过既有权限的文件下载 URL，也不要把新接口当成任意公网代理。</p><p>当前传输是 <code>POST /mcp</code> 请求/响应，不提供独立 SSE 推送；<code>GET</code>/<code>DELETE /mcp</code> 返回 <code>405</code> 是接口约定，不是故障。让客户端适配真实传输，而不是仅修改文档承诺 SSE。</p><h2 id="状态变更与失败恢复" tabindex="-1">状态变更与失败恢复 <a class="header-anchor" href="#状态变更与失败恢复" aria-label="Permalink to &quot;状态变更与失败恢复&quot;">​</a></h2><p>设计清楚“接受”“执行中”“终态”和“实际生效”。带副作用的请求超时后先查询状态，不盲目重试。需要多阶段提交时明确持久状态、重放/幂等规则和恢复入口。</p><p>配置或密钥切换应先可靠持久化，再推进不可逆的清理或运行时状态。并发共享数据使用已有同步机制；不要把 <code>sync</code>/原子字段放进经常按值复制的响应结构。</p><h2 id="贡献时附带什么" tabindex="-1">贡献时附带什么 <a class="header-anchor" href="#贡献时附带什么" aria-label="Permalink to &quot;贡献时附带什么&quot;">​</a></h2><p>提交接口契约、权限矩阵、回归案例、必要数据迁移/回退说明，以及<a href="/developer/testing.html">测试证据</a>。涉及 Agent/protobuf 时列出配对提交；新增 UI 路由还要检查<a href="/developer/theme-development.html">SPA HTTP 状态回退</a>。</p><p>权威实现参考：<a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/controller.go" target="_blank" rel="noreferrer">路由</a>、<a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/scope_doc.go" target="_blank" rel="noreferrer">scope 对照</a>、<a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/mcp.go" target="_blank" rel="noreferrer">MCP 实现</a>。</p>',20)])])}const b=o(r,[["render",c]]);export{m as __pageData,b as default};
